import { test, expect, Page } from '@playwright/test';

test.describe('File Upload Success Checkmark', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000/upload');
  });

  test('should display success checkmark when file upload completes', async () => {
    // Set up file to upload
    const filePath = 'test-files/sample.pdf';

    // Find and interact with file input
    const fileInput = page.locator('input[type="file"]');
    await fileInput.setInputFiles(filePath);

    // Wait for upload to complete and verify success checkmark appears
    const successCheckmark = page.getByRole('img', { name: /success|checkmark|check/i });
    await expect(successCheckmark).toBeVisible({ timeout: 10000 });

    // Verify checkmark has correct attributes
    await expect(successCheckmark).toHaveAttribute('alt', /success|checkmark|check/i);
  });

  test('should show success message with checkmark after upload', async () => {
    const filePath = 'test-files/document.txt';

    // Upload file
    const fileInput = page.locator('input[type="file"]');
    await fileInput.setInputFiles(filePath);

    // Verify success message appears
    const successMessage = page.getByText(/upload successful|file uploaded|upload complete/i);
    await expect(successMessage).toBeVisible({ timeout: 10000 });

    // Verify checkmark icon is present near success message
    const checkmarkIcon = page.getByRole('img', { name: /checkmark|check|success/i });
    await expect(checkmarkIcon).toBeVisible();

    // Verify checkmark and message are in same container
    const successContainer = page.locator('[data-testid="upload-success"]');
    await expect(successContainer).toContainText(/upload successful|file uploaded/i);
  });

  test('should display checkmark with file name after successful upload', async () => {
    const filePath = 'test-files/image.jpg';
    const fileName = 'image.jpg';

    // Upload file
    const fileInput = page.locator('input[type="file"]');
    await fileInput.setInputFiles(filePath);

    // Wait for success state
    const uploadStatus = page.getByRole('status');
    await expect(uploadStatus).toContainText(/complete|success|uploaded/i, { timeout: 10000 });

    // Verify checkmark is visible
    const checkmark = page.getByRole('img', { name: /checkmark|success/i });
    await expect(checkmark).toBeVisible();

    // Verify file name is displayed with checkmark
    const fileNameDisplay = page.getByText(new RegExp(fileName, 'i'));
    await expect(fileNameDisplay).toBeVisible();
  });

  test('should animate checkmark on successful file upload', async () => {
    const filePath = 'test-files/data.csv';

    // Upload file
    const fileInput = page.locator('input[type="file"]');
    await fileInput.setInputFiles(filePath);

    // Find checkmark element
    const checkmark = page.getByRole('img', { name: /checkmark|success/i });

    // Wait for checkmark to appear
    await expect(checkmark).toBeVisible({ timeout: 10000 });

    // Verify animation class or style is applied
    const animatedCheckmark = page.locator('[class*="animate"], [class*="success"]').filter({ has: checkmark });
    await expect(animatedCheckmark).toHaveCount(1);
  });

  test('should display checkmark for multiple file uploads', async () => {
    const files = ['test-files/file1.pdf', 'test-files/file2.txt'];

    // Upload first file
    const fileInput = page.locator('input[type="file"]');
    await fileInput.setInputFiles(files[0]);

    // Verify first checkmark appears
    const firstCheckmark = page.getByRole('img', { name: /checkmark|success/i }).first();
    await expect(firstCheckmark).toBeVisible({ timeout: 10000 });

    // Upload second file
    await fileInput.setInputFiles(files[1]);

    // Verify second checkmark appears
    const allCheckmarks = page.getByRole('img', { name: /checkmark|success/i });
    await expect(allCheckmarks).toHaveCount(2, { timeout: 10000 });
  });

  test('should show checkmark with upload progress completion', async () => {
    const filePath = 'test-files/large-file.zip';

    // Upload file
    const fileInput = page.locator('input[type="file"]');
    await fileInput.setInputFiles(filePath);

    // Wait for progress bar to complete
    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toHaveAttribute('aria-valuenow', '100', { timeout: 15000 });

    // Verify checkmark appears after progress completes
    const checkmark = page.getByRole('img', { name: /checkmark|success/i });
    await expect(checkmark).toBeVisible();

    // Verify progress bar is hidden or disabled after completion
    await expect(progressBar).not.toBeVisible();
  });
});
